"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[674],{3674:(e,o,a)=>{a.d(o,{pC:()=>s,Tw:()=>r,_I:()=>i,bd:()=>l,is:()=>d});let t=JSON.parse('[{"slug":"uspesne-stehovani-uff0","typ":"Prodej","lokalita":"Mělnicko","badge":"Rodinn\xe1 situace","nazev":"\xdaspěšn\xe9 stěhov\xe1n\xed","text":"Mal\xfd panel\xe1ček kousek od Měln\xedka mi byl doporučen jedn\xedm klientem, respektive j\xe1 byl doporučen kamar\xe1dovi majitele jednoho z bytů. Rodina potřebovala byt prodat, aby financovali rekonstrukci rodinn\xe9ho domu. A nebyl moc prostor pro ž\xe1dn\xe9 slevy ani př\xe1telskou cenu. Přizn\xe1m se, že jsem moc nevěděl, co čekat od t\xe9to lokality a kupn\xed s\xedly v okol\xed. Ale povedlo se poměrně rychle naj\xedt šikovn\xe9ho mlad\xe9ho z\xe1jemce, kter\xfd měl vyřešeno financov\xe1n\xed a dovedl si představit, jak nalož\xed s rekonstrukc\xed. Všechno dobře dopadlo i d\xedky perfektn\xed prezentaci, kter\xe1 zaručila, že si kupuj\xedc\xed zvl\xe1dl prom\xedtnout, jak byt vypad\xe1, když v něm nebydl\xed 4 lid\xe9. :) ","foto":"242dcff8883154f61ce9924ffcc49167.jpg"},{"slug":"rekonstrukce-na-vinohradech-e1g3","typ":"Pron\xe1jem","lokalita":"Vinohrady","badge":"Rodinn\xe9 bydlen\xed ","nazev":"Rekonstrukce na Vinohradech","text":"Kr\xe1sn\xfd byt po rekonstrukci se majitelům nedařilo pronajmout, takže přijali r\xe1di mou pomoc založenou na pečliv\xe9m studiu situace. Až j\xe1 jsem dok\xe1zal zohlednit absenci v\xfdtahu v domě, kde ob\xfdvat tento byt bohužel znamenalo vyj\xedt 4 podlaž\xed - a z\xe1roveň nesn\xedžit cenu pod hranici odpov\xeddaj\xedc\xed vynikaj\xedc\xed n\xe1kladn\xe9 rekonstrukci. Z\xe1roveň jsem opět doručil perfektn\xedho n\xe1jemce na \xfarovni bez nutnosti dělat kompromis, snižovat cenu nebo něco z bytu odstraňovat. ","foto":"69569b0ace123f0af61f67f2548425db.jpg"},{"slug":"luxusni-prvorepublikovy-byt-4kk","typ":"Pron\xe1jem","lokalita":"Praha","badge":"Pr\xe9miov\xe1 adresa","nazev":"Luxusn\xed prvorepublikov\xfd byt 4+kk po rekonstrukci","text":"Tady bylo z\xe1sadn\xed naj\xedt klienta, kter\xfd je dostatečně solventn\xed, spolehliv\xfd a\xa0vydrž\xed zde bydlet dlouho\xa0– měl to b\xfdt konec konců prvn\xed n\xe1jemce po n\xe1kladn\xe9 renovaci, v\xfdměně kuchyně a\xa0koupelny. Luxusn\xed byt na hezk\xe9 adrese, kde m\xe1te sousedů jen p\xe1r, ale jsou fajn a\xa0rozum\xedte si. Ide\xe1ln\xed zak\xe1zka pro m\xe9 uměn\xed spr\xe1vn\xe9 volby n\xe1jemce.","foto":"/images/realizace-01.jpg"},{"slug":"byt-v-panelacku-v-malesicich","typ":"Prodej","lokalita":"Praha\xa0– Malešice","badge":"Prod\xe1no za 3 t\xfddny","nazev":"Byt v\xa0panel\xe1čku v\xa0Malešic\xedch","text":"Byt před rekonstrukc\xed s\xa0n\xe1jemci a\xa0v\xa0původn\xedm stavu. Z\xa0toho by někdo mohl m\xedt strach, ale mě to bav\xed. N\xe1jemn\xedci šli jinam, byt se vyklidil a\xa0trochu vymaloval. Zbytek udělaly fotografie a\xa0AI staging. Odprezentovali jsme to tak hezky, že bylo dost z\xe1jemců na nav\xfdšen\xed kupn\xed ceny o\xa0125\xa0000\xa0Kč a\xa0zvl\xe1dnut\xed prodeje během 21\xa0dnů od podpisu smlouvy s\xa0majiteli.","foto":"/images/realizace-02.jpg"},{"slug":"krasny-dum-v-praze","typ":"Prodej","lokalita":"Horn\xed Počernice","badge":"Třet\xed makl\xe9ř v\xa0pořad\xed\xa0– a\xa0prod\xe1no","nazev":"Kr\xe1sn\xfd dům v\xa0Praze","text":"Byl jsem asi třet\xed, kdo jej zkoušel prodat. A\xa0se vš\xed pokorou mus\xedm prozradit, že se to povedlo. Jedna z\xa0nemovitost\xed, do kter\xe9 jsem se zamiloval na prvn\xed pohled\xa0– slunce ze všech stran od r\xe1na do večera, baz\xe9n, v\xedřivka, grilov\xe1n\xed na zahradě, terasa, gar\xe1ž a\xa0chytře řešen\xe9 \xfaložn\xe9 prostory. A\xa0božsk\xfd klid a\xa0zeleň všude kolem. Ide\xe1ln\xed nemovitost pro to, aby se člověk c\xedtil skvěle každou minutu.","foto":"/images/realizace-03.jpg"},{"slug":"investicni-byt-v-praze","typ":"N\xe1kup + pron\xe1jem","lokalita":"Praha\xa0– Vršovice","badge":"V\xfdnos 5,5\xa0% ročně","nazev":"Investičn\xed byt v\xa0Praze","text":"Mini-př\xedběh o\xa0mal\xe9m bytě s\xa038\xa0m\xb2, kter\xfd jsem ned\xe1vno našel pro jednoho z\xa0m\xfdch klientů. Můj \xfakol byl jednoduch\xfd\xa0– koupit za dobrou cenu. S\xa0vědom\xedm toho jsem se postavil před majitele bytu a\xa0domluvil obchod. Vše proběhlo hladce, klient koupil a\xa0j\xe1 jsem pak byt pronajal za 460\xa0Kč/m\xb2. K\xa0bytu patřil i\xa0sklep o\xa0rozloze 6\xa0m\xb2, kter\xfd jsme pronajali zvl\xe1šť za 2\xa0500\xa0Kč. Celkov\xfd v\xfdnos z\xa0tohoto obchodu byl 5,5\xa0% ročně, což je na Prahu-Vršovice super v\xfdsledek. A\xa0bez stresu.","foto":"/images/realizace-04.jpg"},{"slug":"secesni-skvost","typ":"Pron\xe1jem","lokalita":"Praha\xa0– n\xe1břež\xed","badge":"Pron\xe1jem firemn\xedmu klientovi","nazev":"Secesn\xed skvost","text":"Jeden z\xa0nejhezč\xedch domů v\xa0Praze. Jeho vzhled je poutav\xfd, takže přitahuje pozornost cel\xe9ho n\xe1břež\xed kolem M\xe1nesu. Rekonstrukce byla v\xfdjimečně důkladn\xe1 a\xa0zahrnovala nejen opravu st\xe1vaj\xedc\xedch prvků, ale tak\xe9 implementaci nov\xfdch technologi\xed, zvyšuj\xedc\xed komfort a\xa0zlepšuj\xedc\xed kvalitu života obyvatel. Tento klenot měla možnost pronajmout jen hrstka vybran\xfdch z\xe1jemců a\xa0dnes je provozov\xe1n českou firmou, elitou mezi pronaj\xedmateli.","foto":"/images/realizace-05.jpg"},{"slug":"bytova-vila","typ":"Pron\xe1jem","lokalita":"Praha\xa0– Sm\xedchov","badge":"Pron\xe1jem na \xfarovni","nazev":"Bytov\xe1 vila","text":"Kr\xe1sn\xfd prostorn\xfd byt v\xa0supermodern\xed bytov\xe9 vile na Sm\xedchově\xa0– bylo důležit\xe9 obsadit jej perfektn\xedmi n\xe1jemci, protože v\xa0druh\xe9m bytě bydleli majitel\xe9. Soukrom\xe1 sauna je lepš\xed než veřejn\xe1, obzvl\xe1šť když v\xe1s tam odveze v\xfdtah. V\xfdhledy jsou bezkonkurenčn\xed, stejně tak soukrom\xed a\xa0bezpečnost. Zahrada, baz\xe9n, prostorn\xe1 gar\xe1ž a\xa0pohodln\xfd př\xedstup, několik koupelen, balkony a\xa0terasy\xa0– a\xa0to je v\xa0podstatě ještě skromn\xfd v\xfdčet. M\xe1m r\xe1d tyto v\xfdjimečn\xe9 nemovitosti a\xa0jejich pron\xe1jem lidem na \xfarovni.","foto":"/images/realizace-06.jpg"},{"slug":"mezonetovy-byt","typ":"Prodej","lokalita":"Praha\xa0– Holešovice","badge":"Hladk\xfd průběh u\xa0n\xe1ročn\xfdch klientů","nazev":"Mezonetov\xfd byt","text":"Holešovick\xfd byt s\xa0obř\xedm potenci\xe1lem růstu ceny… detaily neprozrad\xedm, ty zn\xe1 nov\xfd majitel. Mezonety se neprod\xe1vaj\xed nejl\xe9pe\xa0– jejich věhlas už nen\xed takov\xfd jako na přelomu tis\xedcilet\xed, ovšem když je byt dobře postaven\xfd a\xa0m\xe1 potenci\xe1l pro dalš\xed chytr\xe9 \xfapravy, jedn\xe1 se o\xa0super koupi. Prod\xe1vaj\xedc\xed byli n\xe1ročn\xed, což je v\xa0poř\xe1dku\xa0– o\xa0to v\xedc mě těš\xed, že vše proběhlo hladce.","foto":"/images/realizace-07.jpg"},{"slug":"pronajem-bytu-smichov","typ":"Pron\xe1jem","lokalita":"Praha\xa0– Sm\xedchov","badge":"Architektonick\xfd klenot","nazev":"Pron\xe1jem bytu","text":"Kr\xe1sn\xfd byt k\xa0pron\xe1jmu, kter\xfd byl z\xa0osobn\xedch důvodů srdcovkou. Chtěl jsem, aby n\xe1jemce byl dokonale vybr\xe1n, v\xa0bytě se mu l\xedbilo a\xa0měl skvěl\xfd vztah s\xa0majiteli. Mysl\xedm, že se povedlo. Byt prošel rekonstrukc\xed pod dohledem v\xfdjimečn\xe9ho architekta, kter\xfd působ\xed po cel\xe9m světě a\xa0umně spojil historick\xe9 prvky s\xa0modern\xed dom\xe1cnost\xed. Odrazil i\xa0současn\xfd trend z\xe1liby v\xa0pr\xe1ci z\xa0domova, takže kuchyně s\xa0j\xeddelnou se za pět vteřin proměn\xed v\xa0kancel\xe1ř, ze kter\xe9 lze streamovat videokonferenci.","foto":"/images/realizace-08.jpg"},{"slug":"byt-k-rekonstrukci","typ":"Prodej","lokalita":"Praha 4\xa0– Michle","badge":"Prod\xe1no přes 6 konkurenčn\xedch nab\xeddek","nazev":"Byt k\xa0rekonstrukci","text":"Byt v\xa0Michli s\xa0v\xfdbornou dispozic\xed, balkonem a\xa0sklepem. Udržovan\xfd dům s\xa0poctiv\xfdm a\xa0zodpovědn\xfdm SVJ. Byt byl však před rekonstrukc\xed a\xa0jeho prezentace nebyla nic snadn\xe9ho, protože posledn\xed n\xe1jemce jej poměrně „vybydlel“. Jsme ovšem v\xfdborn\xfd t\xfdm profesion\xe1lů, takže jsme si poradili a\xa0prezentaci vyrobili tak l\xe1kavou, že se byt prodal i\xa0v\xa0konkurenci dalš\xedch šesti podobn\xfdch nab\xeddek okolo. Velkou roli hr\xe1ly i\xa0obchodn\xed dovednosti a\xa0trpělivost.","foto":"/images/realizace-09.jpg"},{"slug":"investicni-byt-stodulky","typ":"Prodej","lokalita":"Praha\xa0– Stodůlky","badge":"Bez slev z\xa0ceny","nazev":"Investičn\xed byt Stodůlky","text":"Novostavba, byt 2+kk se sklepem a\xa0lodži\xed\xa0– co může b\xfdt lepš\xedho pro drobnou investici, nav\xedc ve skvěl\xe9 lokalitě u\xa0metra, př\xedrody a\xa0mimo panelovou z\xe1stavbu. Pln\xe1 občansk\xe1 vybavenost př\xedmo za domem, kter\xfd je v\xa0super kondici a\xa0m\xe1 dva v\xfdtahy. Byt se prodal i\xa0s\xa0n\xe1bytkem a\xa0majitel neměl s\xa0nič\xedm ž\xe1dnou velkou pr\xe1ci, jen se odstěhovat. Byt z\xa0roku 2015 byl udržov\xe1n v\xa0super stavu a\xa0kupuj\xedc\xed dostali velmi dobrou hodnotu za sv\xe9 pen\xedze. A\xa0nemuseli jsme zlevňovat.","foto":"/images/realizace-10.jpg"},{"slug":"pronajem-bytu-dejvice","typ":"Pron\xe1jem","lokalita":"Praha\xa0– Dejvice","badge":"Pečlivě vybran\xfd n\xe1jemce","nazev":"Pron\xe1jem bytu","text":"Kr\xe1sn\xfd byt k\xa0pron\xe1jmu v\xa0jedn\xe9 z\xa0nejž\xe1danějš\xedch lokalit. Prošel rekonstrukc\xed a\xa0zachoval všechny historick\xe9 prvky, m\xe1 tedy speci\xe1ln\xed atmosf\xe9ru. Bylo důležit\xe9, aby n\xe1jemce byl vybr\xe1n velmi pečlivě, protože c\xedlem bylo zachovat harmonii domu a\xa0př\xe1telskou rodinnou atmosf\xe9ru obyvatel. Mohu ř\xedct, že se povedlo a\xa0j\xe1 jsem dok\xe1zal b\xfdt přidanou hodnotou, za kterou mi klienti plat\xed, nikoliv jen inzerent, telefonista a\xa0otev\xedrač dveř\xed.","foto":"/images/realizace-11.jpg"},{"slug":"investicni-byt-v-michli","typ":"Prodej","lokalita":"Praha\xa0– Michle","badge":"Prodej i\xa0v\xa0chladn\xe9m l\xe9tě","nazev":"Investičn\xed byt v\xa0Michli","text":"Investičn\xed byt, ze kter\xe9ho se majitel\xe9 stěhovali neradi, protože byl prostě skvěl\xfd. Šli jsme jej prod\xe1vat přesně v\xa0obdob\xed, kdy se začal realitn\xed trh zastavovat, a\xa0konkurence v\xa0t\xe9to lokalitě měla tak\xe9 co nab\xeddnout. Dokonce jsme měli už skoro prod\xe1no, avšak kupuj\xedc\xed začal kličkovat a\xa0snažil se n\xe1s „nat\xe1hnout“, tak jsme raději šli naj\xedt jin\xe9ho. D\xedky perfektn\xed prezentaci a\xa0aktivn\xed pr\xe1ci s\xa0nab\xeddkou jsme i\xa0během chladn\xe9ho l\xe9ta našli z\xe1jemce s\xa0hotovost\xed.","foto":"/images/realizace-12.jpg"},{"slug":"hezky-byt-2kk","typ":"Prodej","lokalita":"Praha\xa0– Vršovice","badge":"+250\xa0000\xa0Kč po provizi","nazev":"Hezk\xfd byt 2+kk","text":"Investičn\xed byt 2+kk v\xa0Praze po č\xe1stečn\xe9 rekonstrukci. Majitelům jsme pomohli s\xa0nezbytn\xfdmi opravami po nepoř\xe1dn\xfdch n\xe1jemc\xedch a\xa0našli solidn\xedho kupce s\xa0hotovost\xed. K\xa0propagaci bytu se nat\xe1čelo video, což je u\xa0n\xe1s samozřejm\xe9 narozd\xedl od většiny makl\xe9řů a\xa0kancel\xe1ř\xed. Provedli jsme 13 prohl\xeddek, ze kter\xfdch vzešli tři z\xe1jemci. Vše šlo hladce d\xedky zodpovědn\xe9 komunikaci na obě strany. Majitel\xe9 z\xedskali i\xa0po započten\xed provize o\xa0čtvrt milionu v\xedce.","foto":"/images/realizace-13.jpg"},{"slug":"prakticky-byt-pro-rodinu","typ":"Prodej","lokalita":"Praha","badge":"Prodej s\xa0n\xe1jemci v\xa0bytě","nazev":"Praktick\xfd byt pro rodinu","text":"Praktick\xfd byt 3+kk se prod\xe1val i\xa0s\xa0n\xe1jemci, nicm\xe9ně nov\xfd majitel chtěl v\xa0bytě bydlet s\xe1m. Bylo potřeba vše koordinovat tak, aby obchod proběhl hladce a\xa0nikdo neměl zbytečn\xfd stres nebo špatn\xfd pocit z\xa0cel\xe9 situace. Původn\xed majitel si př\xe1l m\xedt co nejm\xe9ně starost\xed, běh\xe1n\xed a\xa0zařizov\xe1n\xed, což jsme mu sl\xedbili a\xa0zař\xeddili\xa0– prostě jen podepsal kupn\xed smlouvu. Rozsah autonomie, kter\xfd dostanu, je na v\xe1s, můžete klidně b\xfdt u\xa0každ\xe9ho kroku osobně.","foto":"/images/realizace-14.jpg"},{"slug":"pozemek-ve-vranem","typ":"Prodej","lokalita":"Vran\xe9 nad Vltavou","badge":"2\xd7 tržn\xed cena lokality","nazev":"Pozemek ve Vran\xe9m","text":"Neobyčejn\xfd pozemek a\xa0tedy nab\xeddka, kter\xe1 už se nebude opakovat\xa0– v\xfdhled na Vltavu ze sk\xe1ly a\xa0rohov\xe1 poloha, takže majitel domu, kter\xfd zde vyroste, nepřijde nikdy o\xa0v\xfdhled a\xa0soukrom\xed. Majitel\xe9 požadovali dvojn\xe1sobek tržn\xed ceny v\xa0lokalitě, čehož se povedlo dos\xe1hnout pomoc\xed masivn\xed propagace. Tahle velk\xe1 parcela byla skutečně speci\xe1ln\xed\xa0– jen bylo třeba naj\xedt z\xe1jemce, kter\xfd to ocen\xed.","foto":"/images/realizace-15.jpg"},{"slug":"krasny-dum-na-smichove","typ":"Prodej","lokalita":"Praha\xa0– Sm\xedchov","badge":"Citliv\xfd rodinn\xfd prodej","nazev":"Kr\xe1sn\xfd dům na Sm\xedchově","text":"Polovina dvojdomu v\xa0Praze, rodinn\xe9 s\xeddlo o\xa0čtyřech podlaž\xedch se zahradou a\xa0stavebn\xedm potenci\xe1lem. Velmi n\xe1ročn\xfd prodej vzhledem k\xa0rodinn\xe9 situaci majitelů. Cena byla vysok\xe1 vzhledem k\xa0existenci př\xedstavku, kter\xfd mohl b\xfdt využit jako tělocvična, provozovna, gar\xe1ž nebo přistavěn k\xa0domu jako rozš\xedřen\xed prvn\xedho podlaž\xed s\xa0terasou.","foto":"/images/realizace-16.jpg"},{"slug":"rodinne-bydleni-bohnice","typ":"Prodej","lokalita":"Praha\xa0– Bohnice","badge":"Bez stresu i\xa0s\xa0n\xe1jemci","nazev":"Rodinn\xe9 bydlen\xed Bohnice","text":"Atypick\xfd byt 4+kk s\xa0v\xfdbornou dispozic\xed a\xa0vš\xedm, co je potřeba\xa0– lodžie, sklep, klimatizace na jižn\xed straně, kr\xe1sn\xfd v\xfdhled a\xa0praktick\xe1 kuchyně. Byt dovoluje upravit velmi jednoduše dispozici ob\xfdvac\xedho pokoje a\xa0pracovny, resp. třet\xed ložnice. V\xa0době prodeje bydleli v\xa0bytě n\xe1jemci, nicm\xe9ně vše opět proběhlo bez komplikac\xed a\xa0nadbytečn\xe9ho stresu. Tak, jak to m\xe1te r\xe1di.","foto":"/images/realizace-17.jpg"},{"slug":"projekt-na-morave","typ":"Development","lokalita":"Morava","badge":"3 luxusn\xed jednotky","nazev":"Projekt na Moravě","text":"Projekt na Moravě v\xa0podobě tř\xed luxusn\xedch bytov\xfdch jednotek s\xa0důrazem na kvalitu, praktičnost a\xa0n\xedzk\xe9 provozn\xed n\xe1klady bydlen\xed. Unik\xe1tn\xed architektonick\xfd koncept vych\xe1z\xed z\xa0původn\xed secesn\xed fas\xe1dy typick\xe9ho měšťansk\xe9ho domu z\xa0roku 1903 s\xa0prvky modern\xed architektury v\xa0r\xe1mci vnitřn\xedch prostor bytů. Samozřejm\xe9 bylo použit\xed nadstandardn\xedch materi\xe1lů a\xa0zařizovac\xedch prvků.","foto":"/images/realizace-18.jpg"},{"slug":"stavebni-pozemek-u-prahy","typ":"Prodej","lokalita":"Středočesk\xfd kraj","badge":"Nad průměrem lokality","nazev":"Stavebn\xed pozemek u\xa0Prahy","text":"Prodej stavebn\xedho pozemku u\xa0Prahy o\xa0velikosti 1\xa0305\xa0m\xb2. Pozitivn\xed byla existence zas\xedťov\xe1n\xed, občansk\xe1 vybavenost v\xa0okol\xed a\xa0skvěl\xfd voln\xfd v\xfdhled, kter\xfd nesm\xed b\xfdt zastavěn. Negativem byla relativn\xed bl\xedzkost letiště, kter\xe9 však nen\xed využ\xedv\xe1no denně. I\xa0proto jsme nemohli leg\xe1lně využ\xedt z\xe1běry z\xa0dronu. Stejně jsme dos\xe1hli prodejn\xed ceny, kter\xe1 převyšovala průměr v\xa0lokalitě. Obchod proběhl hladce a\xa0poměrně rychle, všichni spokojeni. Na pozemku vyroste rodinn\xfd dům s\xa0kr\xe1snou zahradou.","foto":"/images/realizace-19.jpg"}]'),n=JSON.parse('[{"q":"Jak dlouho trv\xe1 prodej nemovitosti?","a":"Doba prodeje se liš\xed podle tržn\xedch podm\xednek, lokality a\xa0zvolen\xe9 strategie. V\xa0Praze se dobře připraven\xfd byt obvykle prod\xe1 během několika t\xfddnů až měs\xedců\xa0– byt v\xa0Malešic\xedch se prodal za 21\xa0dnů od podpisu smlouvy. Re\xe1ln\xfd odhad pro vaši nemovitost v\xe1m řeknu hned při prvn\xed konzultaci."},{"q":"Jak\xe9 jsou n\xe1klady spojen\xe9 s\xa0prodejem?","a":"Mezi hlavn\xed n\xe1klady patř\xed provize, pr\xe1vn\xed služby a\xa0\xfaschova, poplatek katastru a\xa0daň z\xa0př\xedjmu, pokud nesplňujete podm\xednky pro osvobozen\xed. Vše v\xe1m detailně rozep\xedšu předem, abyste věděli, kolik v\xe1m z\xa0prodeje re\xe1lně zůstane."},{"q":"Kolik stoj\xed odhad ceny?","a":"Nic. Orientačn\xed rozpět\xed spoč\xedt\xe1te př\xedmo na tomto webu a\xa0přesn\xe9 oceněn\xed děl\xe1m zdarma v\xa0r\xe1mci osobn\xed konzultace\xa0– bez z\xe1vazku cokoli podepsat. Dostanete p\xedsemn\xfd podklad se srovnateln\xfdmi nab\xeddkami v\xa0lokalitě."},{"q":"Prod\xe1v\xe1te i\xa0byty s\xa0n\xe1jemci nebo v\xa0původn\xedm stavu?","a":"Ano, je to jedna z\xa0m\xfdch specializac\xed. Byt po n\xe1jemc\xedch ani v\xa0původn\xedm stavu nen\xed přek\xe1žka\xa0– n\xe1jemn\xed vztahy, vyklizen\xed, drobn\xe9 opravy i\xa0prezentaci bytu vyřeš\xedm za v\xe1s. Několik takov\xfdch prodejů najdete mezi realizacemi."},{"q":"Můžete prodat nemovitost bez inzerce na realitn\xedch port\xe1lech?","a":"Ano. M\xe1m datab\xe1zi prověřen\xfdch z\xe1jemců, investorů a\xa0spolupracuj\xedc\xedch makl\xe9řů, kter\xfdm nab\xeddku před\xe1m př\xedmo, off market. Diskr\xe9tn\xed prodej se hod\xed u\xa0rodinn\xfdch situac\xed, firemn\xedho majetku i\xa0tam, kde nechcete zbytečnou pozornost sousedů."},{"q":"Jak vyb\xedr\xe1te n\xe1jemce?","a":"Prověřuji zaměstn\xe1n\xed, př\xedjem a\xa0reference od předchoz\xedho pronaj\xedmatele a\xa0s\xa0majitelem si předem řekneme, jak\xfd n\xe1jemce mu sed\xed. C\xedlem nen\xed obsadit byt za každou cenu, ale naj\xedt někoho, kdo plat\xed, zůstane a\xa0o\xa0byt se star\xe1."},{"q":"V\xa0jak\xfdch lokalit\xe1ch působ\xedte?","a":"Předevš\xedm v\xa0Praze a\xa0bl\xedzk\xe9m okol\xed. Mezi realizacemi ale najdete i\xa0pozemek ve Vran\xe9m nad Vltavou, stavebn\xed pozemek ve Středočesk\xe9m kraji nebo developersk\xfd projekt na Moravě\xa0– pokud zak\xe1zka d\xe1v\xe1 smysl, dojedu."},{"q":"Kdo připravuje smlouvy a\xa0kdo drž\xed pen\xedze?","a":"Smlouvy připravuje zkušen\xfd advok\xe1t, se kter\xfdm dlouhodobě spolupracuji, a\xa0kupn\xed cena jde vždy přes \xfaschovu. Zprostředkovatelsk\xe1 smlouva je sestaven\xe1 podle platn\xe9ho realitn\xedho z\xe1kona, kter\xfd chr\xe1n\xed v\xe1s i\xa0mě."}]'),i={jmeno:"Mgr. Jakub Frydrych",znacka:"Frydrych reality",role:"Realitn\xed makl\xe9ř v\xa0Praze",claim:"V\xe1š spolehliv\xfd makl\xe9ř v\xa0Praze\xa0— s\xa0jistotou, zkušenost\xed a\xa0klidem.",obchodniJmeno:"Frydrych reality, s.r.o.",ico:"14376571",dic:"CZ14376571",adresa:"Jaurisova 515/4, Michle, 140 00 Praha 4",ulice:"Jaurisova 515/4",mesto:"Praha 4\xa0– Michle",psc:"140 00",spisovaZnacka:"C 364756 veden\xe1 u\xa0Městsk\xe9ho soudu v\xa0Praze",vznik:"23. 3. 2022",email:"jakub@frydrych-reality.cz",telefon:"+420\xa0603 425\xa0961",telefonRaw:"+420603425961",web:"https://frydrych-reality.cz",lat:50.0594916,lon:14.4490383,googleHodnoceni:"5,0",googleRecenzi:21,oteviraci:"Po až P\xe1 9:00 až 19:00",firmyHodnoceni:"5,0",firmyRecenzi:14,firmyUrl:"https://www.firmy.cz/detail/13730436-frydrych-reality-praha-smichov.html",instagram:"https://www.instagram.com/jf.reality/",instagramJmeno:"@jf.reality",youtube:"https://www.youtube.com/@frydrychreality7195",letPraxe:8,odKdy:2017},l=t,r=n,s=[{id:"praha-1-2",nazev:"Praha 1 a\xa02"},{id:"praha-3-5-6-7",nazev:"Praha 3, 5, 6, 7"},{id:"praha-4-8-9-10",nazev:"Praha 4, 8, 9, 10"},{id:"praha-okraj",nazev:"Okrajov\xe9 č\xe1sti Prahy"},{id:"stredocesky",nazev:"Středočesk\xfd kraj"}],d=[{id:"novostavba",nazev:"Novostavba / po rekonstrukci"},{id:"dobry",nazev:"Dobr\xfd, udržovan\xfd"},{id:"pred-rekonstrukci",nazev:"Před rekonstrukc\xed"}]}}]);